"use client";

// Client-side access to the static dictionary index.
//
// The index files are generated by scripts/build-dict-index.py from
// Tomoshi's open data layer (JMdict / KANJIDIC2 / KanjiVG derived,
// CC BY-SA — see public/dict/ATTRIBUTION.md).
//
// Two access shapes:
//
//   1. lookup.json — one file, ~4 MB raw / ~1 MB gzipped, 30k words.
//      Loaded lazily on first keystroke of the /vocabulary/new form and
//      cached by the browser afterwards. Used for the instant typeahead.
//
//   2. Sharded card data — notes-cn/, notes-rel/, strokes/ are split into
//      256 buckets keyed by FNV-1a(word) so the detail page downloads
//      only the ~12-40 KB it actually needs instead of the whole map.
//
// The shard key MUST match scripts/build-dict-index.py byte for byte.

export interface LookupEntry {
  /** reading (kana) */
  r: string;
  /** Chinese meaning */
  m: string;
  /** part of speech (English, from JMdict) */
  p: string;
  /**
   * Chinese usage example (the Japanese side of the example is not part
   * of the open data layer, so this is a usage hint for the Chinese
   * reader — NOT a Japanese example sentence).
   */
  e: string;
  /** JLPT level from community data, "" if unknown */
  l: string;
  /** frequency rank (lower = more common) */
  f: number;
}

export type LookupMap = Record<string, LookupEntry>;

export interface CnCard {
  summary: string;
  items: Array<{ ja: string; reading: string; note: string }>;
}

export interface RelCard {
  summary: string;
  items: Array<{
    word: string;
    reading: string;
    rel: string;
    formality: string;
    note?: string;
  }>;
}

export interface VerbPair {
  /** the counterpart form (他动词 ↔ 自动词) */
  other: string;
  /** "vt" = transitive (他动词), "vi" = intransitive (自动词) */
  role: "vt" | "vi";
  /** conjugation pattern, e.g. "ru-su" / "aru-eru" */
  pattern: string;
}

/**
 * FNV-1a 32-bit, low byte → 2-hex bucket.
 *
 * Mirrors shard_key() in scripts/build-dict-index.py. If you change one,
 * change the other and regenerate the index.
 */
export function shardKey(word: string): string {
  const bytes = new TextEncoder().encode(word);
  let h = 0x811c9dc5;
  for (let i = 0; i < bytes.length; i++) {
    h ^= bytes[i];
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return (h & 0xff).toString(16).padStart(2, "0");
}

// ---------------------------------------------------------------------------
// Fetch helpers — every fetch is cached for the lifetime of the page so a
// user browsing several words doesn't refetch the same bucket.
// ---------------------------------------------------------------------------

const cache = new Map<string, Promise<unknown>>();

function cachedJson<T>(url: string): Promise<T> {
  const hit = cache.get(url);
  if (hit) return hit as Promise<T>;
  const p = fetch(url)
    .then((r) => {
      if (!r.ok) throw new Error(`dict fetch failed: ${url} ${r.status}`);
      return r.json();
    })
    .catch(() => null);
  cache.set(url, p);
  return p as Promise<T>;
}

let lookupPromise: Promise<LookupMap | null> | null = null;

/** Load the 30k-word lookup map. Called on first keystroke, not on mount. */
export function loadLookup(): Promise<LookupMap | null> {
  if (!lookupPromise) {
    lookupPromise = cachedJson<LookupMap>("/dict/lookup.json");
  }
  return lookupPromise;
}

/** Fetch one bucket of a sharded card map and return the entry for `word`. */
export async function fetchCard<T>(
  kind: "notes-cn" | "notes-rel" | "strokes",
  word: string
): Promise<T | null> {
  const bucket = shardKey(word);
  const map = await cachedJson<Record<string, T>>(`/dict/${kind}/${bucket}.json`);
  if (!map) return null;
  return map[word] ?? null;
}

/** Fetch stroke-order paths for several kanji in one round-trip-ish call. */
export async function fetchStrokes(
  kanjis: string[]
): Promise<Record<string, string[]>> {
  const unique = Array.from(new Set(kanjis));
  if (unique.length === 0) return {};

  // Group by bucket so we fetch each bucket exactly once.
  const byBucket = new Map<string, string[]>();
  for (const k of unique) {
    const b = shardKey(k);
    const list = byBucket.get(b) ?? [];
    list.push(k);
    byBucket.set(b, list);
  }

  const out: Record<string, string[]> = {};
  await Promise.all(
    Array.from(byBucket.entries()).map(async ([bucket, keys]) => {
      const map = await cachedJson<Record<string, string[]>>(
        `/dict/strokes/${bucket}.json`
      );
      if (!map) return;
      for (const k of keys) {
        if (map[k]) out[k] = map[k];
      }
    })
  );
  return out;
}

/** The transitive/intransitive pair file is small enough to fetch whole. */
export async function fetchVerbPairs(): Promise<Record<string, VerbPair>> {
  const map = await cachedJson<Record<string, VerbPair>>("/dict/verb_pairs.json");
  return map ?? {};
}

/**
 * Prefix search over the lookup map.
 *
 * The map is a flat object of ~30k entries; a linear scan is ~5 ms in a
 * modern browser, which is well inside a debounce window. Sorting the
 * candidates by frequency rank puts the most useful word first — a word
 * with several readings (訊く / 聞く / 効く) surfaces the common one.
 */
export function searchLookup(
  map: LookupMap,
  query: string,
  limit = 12
): Array<[string, LookupEntry]> {
  const q = query.trim();
  if (!q) return [];

  const out: Array<[string, LookupEntry]> = [];
  for (const key in map) {
    if (key.startsWith(q) || key.includes(q)) {
      out.push([key, map[key]]);
      if (out.length >= limit * 4) break; // enough to sort + cut
    }
  }

  out.sort((a, b) => a[1].f - b[1].f);
  return out.slice(0, limit);
}

/** Japanese kanji only (used for the stroke-order widget). */
export function extractKanji(text: string): string[] {
  return Array.from(text).filter((ch) => {
    const code = ch.codePointAt(0) ?? 0;
    return (
      (code >= 0x3400 && code <= 0x4dbf) || // CJK ext A
      (code >= 0x4e00 && code <= 0x9fff) || // CJK unified
      (code >= 0xf900 && code <= 0xfaff) // compatibility
    );
  });
}
